import axiosConfig from "../axiosConfig"

export const apiCreateSample = async ({ name, strain, header, sequence, length, user_id }) => {
    try {
        const response = await axiosConfig.post('/api/sample/createsample', 
            { name, strain, header, sequence, length },  // Gửi trong body
            { params: { user_id } }  // Gửi user_id trong query params
        );
        return response.data;
    } catch (error) {
        throw new Error(error.message);
    }
};


export const apiGetAllSamplesByUserId = async (user_id) => {
    try {
        const response = await axiosConfig.get('/api/sample/getallsamplesbyuserid', {
            params: { user_id }
        });
        return response.data;
    } catch (error) {
        throw error.message;
    }
};
